    public static int glBegin(StringBuilder t, int pr, int started, int code) {
        if (started == 1) {
            emon.Port.textAscii(t, ",");
        }
        if (pr == 1) {
            Json.jsIndent(t, 3);
        }
        emon.Port.textAscii(t, "\"");
        glkEmitName(t, code);
        emon.Port.textAscii(t, "\":");
        if (pr == 1) {
            emon.Port.textAscii(t, " ");
        }
        return 1;
    }
    public static int glBits(StringBuilder t, int pr, int v, int which) {
        // A bit set as an array of names (which 10 `gq`, 11 `gqf`, 12 `gs`).
        int b = 0;
        int k = 0;
        int bit = 1;
        emon.Port.textAscii(t, "[");
        while (b < 16) {
            if ((v & bit) != 0) {
                Json.jsFsep(t, pr, k);
                emon.Port.textAscii(t, "\"");
                if (which == 10) {
                    gqEmitName(t, bit);
                }
                if (which == 11) {
                    gqfEmitName(t, bit);
                }
                if (which == 12) {
                    gsEmitName(t, bit);
                }
                emon.Port.textAscii(t, "\"");
                k += 1;
            }
            bit *= 2;
            b += 1;
        }
        emon.Port.textAscii(t, "]");
        return 0;
    }
    public static int glField(StringBuilder t, int pr, emon.Port.Cells c, int stride, int row, int r, int started) {
        // One printed field of a row, by row `r` of `gl-fd`.
        int f = GL_FD[r * 6 + 1];
        int kind = GL_FD[r * 6 + 2];
        int key = GL_FD[r * 6 + 3];
        int dflt = GL_FD[r * 6 + 4];
        int arg = GL_FD[r * 6 + 5];
        int p = (row * stride) + f;
        int s = started;
        if (((kind == 1) || ((kind == 2) || (((kind >= 6) && (kind <= 9)) || (kind >= 10)))) && (emon.Port.cellsAt(c, p) == dflt)) {
            return started;
        }
        if (kind == 1) {
            s = glBegin(t, pr, s, key);
            emon.Port.textI32(t, emon.Port.cellsAt(c, p));
            return s;
        }
        if (kind == 2) {
            s = glBegin(t, pr, s, key);
            Json.jsCpt(t, emon.Port.cellsAt(c, p));
            return s;
        }
        if (kind == 3) {
            s = glBegin(t, pr, s, key);
            emon.Port.textAscii(t, "[");
            Json.jsCpt(t, emon.Port.cellsAt(c, p));
            Json.jsFsep(t, pr, 1);
            Json.jsCpt(t, emon.Port.cellsAt(c, p + 1));
            Json.jsFsep(t, pr, 1);
            Json.jsCpt(t, emon.Port.cellsAt(c, p + 2));
            Json.jsFsep(t, pr, 1);
            Json.jsCpt(t, emon.Port.cellsAt(c, p + 3));
            emon.Port.textAscii(t, "]");
            return s;
        }
        if (kind == 4) {
            if ((emon.Port.cellsAt(c, p) == dflt) && (emon.Port.cellsAt(c, p + 1) == arg)) {
                return started;
            }
            s = glBegin(t, pr, s, key);
            emon.Port.textAscii(t, "[");
            emon.Port.textI32(t, emon.Port.cellsAt(c, p));
            Json.jsFsep(t, pr, 1);
            emon.Port.textI32(t, emon.Port.cellsAt(c, p + 1));
            emon.Port.textAscii(t, "]");
            return s;
        }
        if (kind == 5) {
            if (emon.Port.cellsAt(c, p + 1) == dflt) {
                return started;
            }
            s = glBegin(t, pr, s, key);
            emon.Port.textAscii(t, "[\"");
            Evidence.eaEmitName(t, emon.Port.cellsAt(c, p));
            emon.Port.textAscii(t, "\",");
            if (pr == 1) {
                emon.Port.textAscii(t, " ");
            }
            emon.Port.textI32(t, emon.Port.cellsAt(c, p + 1));
            emon.Port.textAscii(t, "]");
            return s;
        }
        if ((kind >= 6) && (kind <= 9)) {
            s = glBegin(t, pr, s, key);
            emon.Port.textAscii(t, "\"");
            if (kind == 6) {
                goEmitName(t, emon.Port.cellsAt(c, p));
            }
            if (kind == 7) {
                Evidence.rsEmitName(t, emon.Port.cellsAt(c, p));
            }
            if (kind == 8) {
                gkEmitName(t, emon.Port.cellsAt(c, p));
            }
            if (kind == 9) {
                rkEmitName(t, emon.Port.cellsAt(c, p));
            }
            emon.Port.textAscii(t, "\"");
            return s;
        }
        if (kind >= 10) {
            s = glBegin(t, pr, s, key);
            glBits(t, pr, emon.Port.cellsAt(c, p), kind);
            return s;
        }
        return started;
    }
    public static int glRow(StringBuilder t, int pr, int a, emon.Port.Cells c, int row) {
        // One row of arena a (1 `grl` .. 4 `grg`) as an object, its fields in stride order.
        int first = GL_FX[(a - 1) * 4 + 0];
        int cnt = GL_FX[(a - 1) * 4 + 1];
        int stride = GL_FX[(a - 1) * 4 + 2];
        int s = 0;
        int k = 0;
        emon.Port.textAscii(t, "{");
        while (k < cnt) {
            s = glField(t, pr, c, stride, row, first + k, s);
            k += 1;
        }
        Json.jsClose(t, pr, 2, s);
        return 0;
    }
    public static int glArena(StringBuilder t, int pr, int started, int a, emon.Port.Cells c) {
        // `"key":[row, ...]` for arena a (1 `grl`, 2 `gfl`, 3 `ggp`, 4 `grg`), as a member of the dump's object; answers 1.
        int stride = GL_FX[(a - 1) * 4 + 2];
        int n = emon.Port.cellsLen(c) / stride;
        int i = 0;
        if (started == 1) {
            emon.Port.textAscii(t, ",");
        }
        if (pr == 1) {
            Json.jsIndent(t, 1);
        }
        emon.Port.textAscii(t, "\"");
        glkEmitName(t, a);
        emon.Port.textAscii(t, "\":");
        if (pr == 1) {
            emon.Port.textAscii(t, " ");
        }
        emon.Port.textAscii(t, "[");
        while (i < n) {
            Json.jsAelem(t, pr, 1, i);
            glRow(t, pr, a, c, i);
            i += 1;
        }
        Json.jsAend(t, pr, 1, n);
        return 1;
    }
    public static int glEmit(StringBuilder t, int pretty, int s0, emon.Port.Cells grl, emon.Port.Cells gfl, emon.Port.Cells ggp, emon.Port.Cells grg) {
        // The four arrays as members of the dump's object, `s0` being 1 when a member came before. Answers 1.
        int s = s0;
        s = glArena(t, pretty, s, 1, grl);
        s = glArena(t, pretty, s, 2, gfl);
        s = glArena(t, pretty, s, 3, ggp);
        s = glArena(t, pretty, s, 4, grg);
        return s;
    }
